require_once '../includes/auth.php'; requireLogin();$tenantId=getCurrentTenantId();$income=0;$expense=0;$q=$conn->query("SHOW TABLES LIKE 'payments'");if($q&&$q->num_rows){$sql="SELECT COALESCE(SUM(amount),0) total FROM payments";if($tenantId)$sql.=" WHERE tenant_id=".(int)$tenantId;$r=$conn->query($sql);$income=$r?(float)$r->fetch_assoc()['total']:0;}$q=$conn->query("SHOW TABLES LIKE 'expenses'");if($q&&$q->num_rows){$sql="SELECT COALESCE(SUM(amount),0) total FROM expenses";if($tenantId)$sql.=" WHERE tenant_id=".(int)$tenantId;$r=$conn->query($sql);$expense=$r?(float)$r->fetch_assoc()['total']:0;}
